);

-- ── 2. Forging catalog rows (migration 790): machine_class, where still NULL.
UPDATE process_taxonomy pt
SET machine_class = v.machine_class
FROM (VALUES
  ($str$Band Saw$str$, $str$forging_band_saw$str$),
  ($str$Conveyor Induction Heat$str$, $str$forging_conveyor_induction_heat$str$),
  ($str$Hammer$str$, $str$forging_hammer$str$),
  ($str$Material Stock$str$, $str$forging_material_stock$str$),
  ($str$Mechanical Press$str$, $str$forging_mechanical_press$str$),
  ($str$Open Die Press$str$, $str$forging_open_die_press$str$),
  ($str$Preheat$str$, $str$forging_oven_furnace$str$),
  ($str$Reheat$str$, $str$forging_oven_furnace$str$),
  ($str$Press$str$, $str$forging_press$str$),
  ($str$Ring Rolling$str$, $str$forging_ring_rolling$str$),
  ($str$Trim$str$, $str$forging_trim$str$)
) AS v(process_name, machine_class)
WHERE pt.process_group = 'Forging' AND pt.process_name = v.process_name AND pt.machine_class IS NULL;

UPDATE process_calculator_mappings pcm
SET machine_class = v.machine_class, updated_at = now()
FROM (VALUES
  ($str$Band Saw$str$, $str$forging_band_saw$str$),
  ($str$Conveyor Induction Heat$str$, $str$forging_conveyor_induction_heat$str$),
  ($str$Hammer$str$, $str$forging_hammer$str$),
  ($str$Material Stock$str$, $str$forging_material_stock$str$),
  ($str$Mechanical Press$str$, $str$forging_mechanical_press$str$),
  ($str$Open Die Press$str$, $str$forging_open_die_press$str$),
  ($str$Preheat$str$, $str$forging_oven_furnace$str$),
  ($str$Reheat$str$, $str$forging_oven_furnace$str$),
  ($str$Press$str$, $str$forging_press$str$),
  ($str$Ring Rolling$str$, $str$forging_ring_rolling$str$),
  ($str$Trim$str$, $str$forging_trim$str$)
) AS v(operation, machine_class)
WHERE pcm.process_group = 'Forging' AND pcm.operation = v.operation AND pcm.machine_class IS NULL;

NOTIFY pgrst, 'reload schema';
